    localStorage.setItem('jarvis_logs', JSON.stringify(logs));
  }, [logs]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const screenVideoRef = useRef<HTMLVideoElement>(document.createElement('video'));
  const screenStreamRef = useRef<MediaStream | null>(null);
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const isScreenActiveRef = useRef(false);
  const isOpticActiveRef = useRef(true);
  const isConnectingRef = useRef(false);

  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  const activeTranscriptionIdRef = useRef<{ OPERATOR: string | null; JARVIS: string | null }>({ OPERATOR: null, JARVIS: null });
  const lastSourceRef = useRef<string | null>(null);

  const isMicMutedRef = useRef(isMicMuted);
  const isJarvisMutedRef = useRef(isJarvisMuted);
  const osControlRef = useRef(osControl);

  useEffect(() => {
    isMicMutedRef.current = isMicMuted;
    isJarvisMutedRef.current = isJarvisMuted;
    osControlRef.current = osControl;
    isOpticActiveRef.current = isOpticActive;
    isScreenActiveRef.current = isScreenActive;
  }, [isMicMuted, isJarvisMuted, osControl, isOpticActive, isScreenActive]);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source, message, timestamp: Date.now(), type
    }].slice(-200));
    lastSourceRef.current = source;
  }, []);

  const updateOrAddLog = useCallback((message: string, source: 'OPERATOR' | 'JARVIS', type: LogEntry['type'] = 'info') => {
    setLogs(prev => {
      const isNewSpeaker = lastSourceRef.current !== source;
      const activeId = !isNewSpeaker ? activeTranscriptionIdRef.current[source] : null;
      const existingIndex = activeId ? prev.findIndex(l => l.id === activeId) : -1;
      if (existingIndex !== -1) {
        const newLogs = [...prev];
        if (newLogs[existingIndex].message === message) return prev;
        newLogs[existingIndex] = { ...newLogs[existingIndex], message, timestamp: Date.now() };
        return newLogs;
      } else {
        const id = Math.random().toString(36).substr(2, 9);
        activeTranscriptionIdRef.current[source] = id;
        lastSourceRef.current = source;
        return [...prev, { id, source, message, timestamp: Date.now(), type }].slice(-200);
      }
    });
  }, []);

  const getSystemInstructionWithMemories = () => {
    const memoryString = memories.map(m => `[${m.category} - ${new Date(m.timestamp).toLocaleDateString()}]: ${m.content}`).join('\n');
    return JARVIS_SYSTEM_INSTRUCTION.replace('{{MEMORY_PLACEHOLDER}}', memoryString || 'No prior memories found.');
  };

  const executeSystemTool = (name: string, args: any) => {
    if (!osControlRef.current) return;

    if (name === 'switch_operating_mode') {
      setMode(args.mode);
      addLog(`⌬ Mode switched to ${args.mode}_MODE`, 'JARVIS', 'info');
    } else if (name === 'toggle_perception_sensor') {
      const { sensor, active } = args;
      if (sensor === 'screen') handleToggleScreenPerception(active);
      if (sensor === 'optic') {
        setIsOpticActive(active);
        isOpticActiveRef.current = active;
        addLog(`⌬ Optic sensor ${active ? 'activated' : 'deactivated'} autonomously.`, 'JARVIS', 'info');
      }
    } else if (name === 'control_audio_interface') {
      const { target, mute } = args;
      if (target === 'mic') {
        setIsMicMuted(mute);
        isMicMutedRef.current = mute;
        addLog(`⌬ Mic ${mute ? 'muted' : 'unmuted'} autonomously.`, 'JARVIS', 'warning');
      }
      if (target === 'voice') {
        setIsJarvisMuted(mute);
        isJarvisMutedRef.current = mute;
        addLog(`⌬ Vocal output ${mute ? 'suspended' : 'active'}.`, 'JARVIS', 'info');
      }
    } else if (name === 'store_memory') {
      const { content, category } = args;
      setMemories(prev => [{ id: Math.random().toString(), content, category, timestamp: Date.now() }, ...prev]);
      addLog(`⌬ Memory logged: [${category}] ${content.substring(0, 30)}...`, 'JARVIS', 'success');
      return true; // Return true to indicate it was handled
    }
    return false;
  };

  const handleSendMessage = async (msg: string, files?: File[]) => {
    if (!msg.trim() && (!files || files.length === 0)) return;

    addLog(msg || (files ? `[Neural Data: ${files.length} packets]` : ""), 'OPERATOR');
    setStatus(JarvisStatus.THINKING);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const parts: any[] = [{ text: msg }];

      if (files && files.length > 0) {
        for (const file of files) {
          const base64Data = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
            reader.readAsDataURL(file);
          });
          parts.push({
            inlineData: { data: base64Data, mimeType: file.type }
          });
        }
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [{ role: 'user', parts }],
        config: {
          systemInstruction: getSystemInstructionWithMemories() + "\nIf requested, provide a very long and detailed intelligence briefing.",
          temperature: 0.7,
          tools: [{ functionDeclarations: toolDeclarations }]
        }
      });

      // Handle function calls from chat
      if (response.functionCalls) {
        let memoryStored = false;
        for (const fc of response.functionCalls) {
          if (executeSystemTool(fc.name, fc.args)) {
            memoryStored = true;
          }
        }

        // If memory was stored, give a confirmation if the text response is empty
        if (memoryStored && !response.text) {
          updateOrAddLog("Sir, the data has been committed to the neural core as requested.", 'JARVIS', 'success');
        }
      }

      const reply = response.text || (response.functionCalls ? "Directives received and executed, Sir." : "Sir, the neural bridge is experiencing high latency.");

      if (reply.length > 800 || msg.toLowerCase().includes('report') || msg.toLowerCase().includes('briefing')) {
        setIntelligenceReport(reply);
        updateOrAddLog("Sir, I have prepared a detailed Intelligence Briefing for you. Viewing on primary HUD.", 'JARVIS');
      } else {
        updateOrAddLog(reply, 'JARVIS');
      }

      // Handle Voice Output
      if (!isJarvisMutedRef.current) {
        setStatus(JarvisStatus.SPEAKING);
        try {
          const ttsResponse = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: reply.substring(0, 500) + (reply.length > 500 ? " (truncated audio)" : "") }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: {
                voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } },
              },
            },
          });

          const audioDataB64 = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
          if (audioDataB64) {
            let outCtx = audioContextRef.current?.output;
            if (!outCtx || outCtx.state === 'closed') {
              outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioBuffer = await decodeAudioData(decode(audioDataB64), outCtx, 24000, 1);
            const source = outCtx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(outCtx.destination);
            source.onended = () => setStatus(JarvisStatus.IDLE);
            source.start();
          }
        } catch (ttsErr) {
          setStatus(JarvisStatus.IDLE);
        }
      } else {
        setStatus(JarvisStatus.IDLE);
      }

    } catch (error: any) {
      addLog(`! Neural Core Anomaly: ${error.message}`, 'SYSTEM', 'error');
      setStatus(JarvisStatus.IDLE);
    }
  };

  const handleNewChat = () => {
    stopLive();
    setActiveSessionId(null);
    setLogs([
      { id: 'sys1', source: 'SYSTEM', message: '● New Neural Session Initialized.', timestamp: Date.now(), type: 'info' }
    ]);
    addLog('» Preparing fresh neural workspace for Operator.', 'SYSTEM', 'success');
  };

  const playClick = useCallback(async () => {
    try {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);
      g.gain.setValueAtTime(0.05, ctx.currentTime);
      g.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.1);
      osc.connect(g);
      g.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.1);
      return ctx;
    } catch(e) { return null; }
  }, []);

  const handleToggleScreenPerception = async (forceState?: boolean) => {
    const target = forceState !== undefined ? forceState : !isScreenActive;
    if (!target) {
      if (screenStreamRef.current) { screenStreamRef.current.getTracks().forEach(t => t.stop()); screenStreamRef.current = null; }
      setIsScreenActive(false); isScreenActiveRef.current = false;
      addLog('⌬ Screen sensor deactivated.', 'SYSTEM', 'info');
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        screenStreamRef.current = stream; screenVideoRef.current.srcObject = stream;
        screenVideoRef.current.play(); setIsScreenActive(true); isScreenActiveRef.current = true;
        addLog('⌬ Screen sensor activated. Analyzing buffer... ⚡', 'JARVIS', 'success');
        stream.getVideoTracks()[0].onended = () => { setIsScreenActive(false); isScreenActiveRef.current = false; };
      } catch (err) { addLog('! Screen access denied.', 'SYSTEM', 'error'); }
    }
  };

  const stopLive = useCallback(() => {
    if (!isLive && !isConnectingRef.current) return;
    setIsLive(false); isConnectingRef.current = false;
    setStatus(JarvisStatus.IDLE);
    activeTranscriptionIdRef.current = { OPERATOR: null, JARVIS: null };
    lastSourceRef.current = null;
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextRef.current) {
      const { input, output } = audioContextRef.current;
      if (input.state !== 'closed') input.close().catch(() => {});
      if (output.state !== 'closed') output.close().catch(() => {});
      audioContextRef.current = null;
    }
    if (cameraStreamRef.current) { cameraStreamRef.current.getTracks().forEach(t => t.stop()); cameraStreamRef.current = null; }
    if (screenStreamRef.current) { screenStreamRef.current.getTracks().forEach(t => t.stop()); screenStreamRef.current = null; }
    if (sessionRef.current) sessionRef.current.close();
    sessionRef.current = null;
    addLog('⊘ Neural Link Terminated. Standing by.', 'SYSTEM', 'warning');
  }, [isLive, addLog]);

  const handleStartLive = async () => {
    if (isLive || isConnectingRef.current) { stopLive(); return; }
    await playClick();
    isConnectingRef.current = true;
    addLog('⌬ Establishing Neural Bridge...', 'SYSTEM', 'info');
    setStatus(JarvisStatus.THINKING);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      await inputCtx.resume(); await outputCtx.resume();
      audioContextRef.current = { input: inputCtx, output: outputCtx };
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: getSystemInstructionWithMemories(),
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } },
          tools: [{ functionDeclarations: toolDeclarations }],
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            isConnectingRef.current = false; setIsLive(true); setStatus(JarvisStatus.LISTENING);
            addLog('⚡ Neural Link established. JARVIS Online. 🤖', 'JARVIS', 'success');
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (inputCtx.state === 'closed' || isMicMutedRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = Math.max(-1, Math.min(1, inputData[i])) * 32767;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s && s.sendRealtimeInput({ media: pcmBlob })).catch(() => {});
            };
            source.connect(scriptProcessor); scriptProcessor.connect(inputCtx.destination);
            frameIntervalRef.current = window.setInterval(() => {
              const activeVideo = isScreenActiveRef.current ? screenVideoRef.current : (isOpticActiveRef.current ? videoRef.current : null);
              if (activeVideo && activeVideo.readyState >= 2) {
                const canvas = canvasRef.current; canvas.width = 640; canvas.height = 480;
                const ctx = canvas.getContext('2d'); ctx?.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => s && s.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } })).catch(() => {});
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 3000);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.toolCall) {
              for (const fc of m.toolCall.functionCalls) {
                executeSystemTool(fc.name, fc.args);
                sessionPromise.then(s => s.sendToolResponse({ functionResponses: [{ id: fc.id, name: fc.name, response: { result: "ok" } }] })).catch(() => {});
              }
            }
            if (m.serverContent?.inputTranscription) { updateOrAddLog(m.serverContent.inputTranscription.text, 'OPERATOR'); setStatus(JarvisStatus.THINKING); }
            if (m.serverContent?.outputTranscription) { 
              const text = m.serverContent.outputTranscription.text;
              updateOrAddLog(text, 'JARVIS'); 
              if (text.length > 500) setIntelligenceReport(text);
              setStatus(JarvisStatus.SPEAKING); 
            }
            const parts = m.serverContent?.modelTurn?.parts;
            if (parts) {
              for (const part of parts) {
                if (part.inlineData?.data) {
                  const outCtx = audioContextRef.current?.output;
                  if (outCtx && outCtx.state !== 'closed') {
                    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                    const buf = await decodeAudioData(decode(part.inlineData.data), outCtx, 24000, 1);
                    if (!isJarvisMutedRef.current) {
                      const src = outCtx.createBufferSource(); src.buffer = buf; src.connect(outCtx.destination);
                      src.onended = () => { sourcesRef.current.delete(src); if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); };
                      src.start(nextStartTimeRef.current); sourcesRef.current.add(src);
                    }
                    nextStartTimeRef.current += buf.duration;
                    setStatus(JarvisStatus.SPEAKING);
                  }
                }
              }
            }
          },
          onerror: () => { addLog(`! Uplink Error`, 'SYSTEM', 'error'); stopLive(); },
          onclose: () => { stopLive(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { addLog(`! Initialization Failed: ${err.message}`, 'SYSTEM', 'error'); isConnectingRef.current = false; setStatus(JarvisStatus.IDLE); }
  };

  const onAddManualMemory = (content: string, category: MemoryEntry['category']) => {
    const newEntry: MemoryEntry = {
      id: Math.random().toString(36).substr(2, 9),
      content,
      category,
      timestamp: Date.now()
    };
    setMemories(prev => [newEntry, ...prev]);
    addLog(`⌬ Manual Memory Entry Saved: [${category}]`, 'SYSTEM', 'success');
  };

  const onDeleteMemory = (id: string) => {
    setMemories(prev => prev.filter(m => m.id !== id));
    addLog(`⌬ Memory Unit Purged: ${id}`, 'SYSTEM', 'warning');
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden">
      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-cyan-500/20 shadow-lg shrink-0">
        <div className="flex items-center gap-12">
          <div className="flex gap-2">
            <button 
              onClick={() => { playClick(); setIsHistoryVisible(!isHistoryVisible); if(isMemoryVisible) setIsMemoryVisible(false); }}
              className={`flex items-center gap-3 px-4 py-2 rounded-lg transition-all duration-300 border ${
                isHistoryVisible ? 'bg-cyan-500/10 border-cyan-400 text-cyan-400 shadow-[0_0_15px_rgba(0,242,255,0.2)]' : 'bg-slate-900/50 border-white/5 text-slate-500 hover:border-cyan-400/40 hover:text-cyan-400'
              }`}
            >
              <HistoryIcon className="w-4 h-4" />
              <span className="text-[10px] font-orbitron tracking-widest uppercase font-bold">Archives</span>
            </button>
            <button 
              onClick={() => { playClick(); setIsMemoryVisible(!isMemoryVisible); if(isHistoryVisible) setIsHistoryVisible(false); }}
              className={`flex items-center gap-3 px-4 py-2 rounded-lg transition-all duration-300 border ${
                isMemoryVisible ? 'bg-cyan-500/10 border-cyan-400 text-cyan-400 shadow-[0_0_15px_rgba(0,242,255,0.2)]' : 'bg-slate-900/50 border-white/5 text-slate-500 hover:border-cyan-400/40 hover:text-cyan-400'
              }`}
            >
              <BrainCircuit className="w-4 h-4" />
              <span className="text-[10px] font-orbitron tracking-widest uppercase font-bold">Memory</span>
            </button>
          </div>

          <div className="flex flex-col">
            <div className="flex items-center gap-2 text-cyan-400 font-orbitron text-base tracking-[0.2em] text-glow">
              <Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}
            </div>
          </div>
        </div>

        <div className="hidden lg:flex items-center gap-3">
            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button key={m} onClick={() => { playClick(); setMode(m); }} className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${mode === m ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow' : 'border-white/5 text-slate-500 hover:border-white/20'}`}>
                {m}
              </button>
            ))}
        </div>

        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase font-bold">STATUS: {status}</span>
          </div>
          <button onClick={stopLive} className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg font-bold tracking-widest">
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 pb-0 gap-6 relative">
        <ChatHistoryPanel 
          isVisible={isHistoryVisible}
          activeSessionId={activeSessionId} 
          onSelectSession={(id) => { playClick(); setActiveSessionId(id); }} 
          onNewChat={handleNewChat}
        />

        {isMemoryVisible && (
          <div className="w-96 h-full animate-in slide-in-from-left duration-500 z-40">
            <MemoryPanel 
              memories={memories} 
              onAddMemory={onAddManualMemory}
              onDeleteMemory={onDeleteMemory}
            />
          </div>
        )}

        <SystemMetrics />

        <div className="flex-1 flex flex-col gap-0 relative">
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40">
            <HudCore status={status} />
          </div>

          <div className="z-20 flex-1 flex flex-col overflow-hidden">
            <div className={`flex-1 glass rounded-t-xl overflow-hidden flex flex-col shadow-2xl border-white/10 border-b-0 relative transition-all duration-700`}>
               {intelligenceReport ? (
                 <div className="relative h-full">
                    <button 
                      onClick={() => setIntelligenceReport(null)}
                      className="absolute top-4 right-4 z-50 p-2 bg-black/50 border border-white/10 rounded-full text-slate-400 hover:text-cyan-400 transition-colors"
                    >
                      <X className="w-5 h-5" />
                    </button>
                    <IntelligenceBriefing content={intelligenceReport} />
                 </div>
               ) : (
                 <Terminal logs={logs} />
               )}
            </div>

            <ChatBox 
              onSendMessage={handleSendMessage} 
              waveform={
                <Waveform 
                  isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                  color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : status === JarvisStatus.DIAGNOSTIC ? '#fbbf24' : '#0041ff'} 
                />
              } 
            />
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </div>

      <footer className="h-20 glass border-t border-cyan-500/20 flex items-center justify-center gap-6 z-50 shrink-0 px-4">
        <ControlButton icon={Mic} label="NEURAL" active={isLive} onClick={handleStartLive} color="cyan" disabled={isConnectingRef.current} />
        <ControlButton icon={isMicMuted ? MicOff : Mic} label="MIC_SENSE" active={!isMicMuted} onClick={() => { playClick(); setIsMicMuted(!isMicMuted); }} color={isMicMuted ? "red" : "cyan"} />
        <ControlButton icon={isJarvisMuted ? VolumeX : Volume2} label="JARVIS_VOICE" active={!isJarvisMuted} onClick={() => { playClick(); setIsJarvisMuted(!isJarvisMuted); }} color={isJarvisMuted ? "red" : "blue"} />
        <ControlButton icon={Monitor} label="OPTIC" active={isOpticActive} onClick={() => { playClick(); setIsOpticActive(!isOpticActive); }} color="blue" />
        <ControlButton icon={Layout} label="SCREEN" active={isScreenActive} onClick={() => handleToggleScreenPerception()} color="purple" />
        <ControlButton icon={Database} label="MEMORY" active={isMemoryVisible} color="cyan" onClick={() => { playClick(); setIsMemoryVisible(!isMemoryVisible); }} />
        <ControlButton icon={Settings} label="CONFIG" color="slate" onClick={() => setIsSettingsOpen(true)} />
        <ControlButton icon={TerminalIcon} label="COMMAND" color="cyan" onClick={() => { playClick(); setIntelligenceReport(null); addLog('⌬ Command Input: Primary Terminal Focus Re-established.', 'JARVIS', 'info'); }} />
      </footer>

      <SettingsPanel 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        osControl={osControl} 
        setOsControl={setOsControl} 
      />
    </div>
  );
};

const ControlButton = ({ icon: Icon, label, active, onClick, color, disabled }: any) => {
  const colorMap: any = {
    cyan: 'text-cyan-400 border-cyan-500/30 bg-cyan-500/5 hover:border-cyan-400',
    blue: 'text-blue-400 border-blue-500/30 bg-blue-500/5 hover:border-blue-400',
    purple: 'text-purple-400 border-purple-500/30 bg-purple-500/5 hover:border-purple-400',
    slate: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
    red: 'text-red-500 border-red-500/30 bg-red-500/5 hover:border-red-400',
  };
  return (
    <button onClick={onClick} disabled={disabled} className={`group flex flex-col items-center gap-1.5 transition-all duration-300 transform hover:-translate-y-1 active:scale-95 ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}>
      <div className={`w-10 h-10 rounded-full border flex items-center justify-center transition-all duration-500 ${colorMap[color]} ${active && color !== 'red' ? 'shadow-[0_0_20px_rgba(0,242,255,0.4)] border-cyan-400 bg-cyan-500/20' : active && color === 'red' ? 'shadow-[0_0_20px_rgba(239,68,68,0.4)] border-red-500 bg-red-500/20' : ''}`}>
        <Icon className={`w-4 h-4 ${active ? 'animate-pulse' : ''}`} />
      </div>
      <span className={`text-[8px] font-orbitron tracking-[0.2em] transition-colors uppercase font-bold ${active && color !== 'red' ? 'text-white text-glow' : active && color === 'red' ? 'text-red-400' : 'text-slate-500 group-hover:text-cyan-400'}`}>{label}</span>
    </button>
  );
};

export default App;

