    if (!cleanUrl.startsWith('http')) cleanUrl = 'https://' + cleanUrl;
    if (cleanUrl.includes('google.com') && !cleanUrl.includes('igu=1')) {
      cleanUrl = 'https://www.google.com/search?q=' + encodeURIComponent(url) + '&igu=1';
