  });

  const [memories, setMemories] = useState<MemoryEntry[]>(() => {
    const saved = localStorage.getItem('jarvis_memories');
    return saved ? JSON.parse(saved) : [
      { id: 'm1', category: 'User', content: 'Operator prefers dark-mode HUD interfaces.', timestamp: Date.now() - 100000 },
      { id: 'm2', category: 'Goal', content: 'Current objective: Neural Link optimization for Mark-III.', timestamp: Date.now() - 50000 },
