      { id: '1', source: 'SYSTEM', message: '● JARVIS OS Mark-III v11.2 Initialized.', timestamp: Date.now(), type: 'success' },
      { id: '2', source: 'SYSTEM', message: '» Neural Core: Active. Secure Link Ready.', timestamp: Date.now() + 50, type: 'info' },
    ];
