      if ((window as any).aistudio?.openSelectKey) {
        await (window as any).aistudio.openSelectKey();
        setActiveTier('PAID');
      }
    } catch (error) {
      console.error("Failed to initiate Key Sync Protocol:", error);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="w-full max-w-lg glass border border-cyan-500/30 rounded-2xl shadow-[0_0_50px_rgba(0,242,255,0.2)] overflow-hidden flex flex-col max-h-[90vh]">
        <div className="flex items-center justify-between px-6 py-4 border-b border-cyan-500/20 bg-cyan-500/5">
          <div className="flex items-center gap-3">
            <Cpu className="w-5 h-5 text-cyan-400" />
            <h2 className="text-sm font-orbitron font-bold tracking-[0.2em] text-cyan-400 uppercase">System_Config_Matrix</h2>
          </div>
          <button onClick={onClose} className="text-slate-500 hover:text-cyan-400 transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scroll">
          {/* Neural Link Protocol (Tier Selection) */}
          <div className="space-y-6">
            <h3 className="text-[10px] font-orbitron text-cyan-500/60 uppercase tracking-widest flex items-center gap-2">
              <KeyRound className="w-3 h-3" /> Neural_Link_Uplink_Tier
            </h3>

            <div className="grid grid-cols-2 gap-3 mb-4">
              <button 
                onClick={() => setActiveTier('FREE')}
                className={`p-3 border rounded-lg flex flex-col items-center gap-2 transition-all ${
                  activeTier === 'FREE' 
                    ? 'bg-cyan-500/10 border-cyan-400 shadow-[0_0_15px_rgba(0,242,255,0.1)]' 
                    : 'bg-black/20 border-white/5 opacity-50 hover:opacity-100'
                }`}
              >
                <Globe className={`w-4 h-4 ${activeTier === 'FREE' ? 'text-cyan-400' : 'text-slate-400'}`} />
                <span className={`text-[9px] font-orbitron font-bold tracking-widest ${activeTier === 'FREE' ? 'text-cyan-400' : 'text-slate-400'}`}>SYSTEM_FREE</span>
              </button>
              <button 
                onClick={() => setActiveTier('PAID')}
                className={`p-3 border rounded-lg flex flex-col items-center gap-2 transition-all ${
                  activeTier === 'PAID' 
                    ? 'bg-amber-500/10 border-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.1)]' 
                    : 'bg-black/20 border-white/5 opacity-50 hover:opacity-100'
                }`}
              >
                <Lock className={`w-4 h-4 ${activeTier === 'PAID' ? 'text-amber-400' : 'text-slate-400'}`}>
                  <Lock className="w-4 h-4" />
                </Lock>
                <span className={`text-[9px] font-orbitron font-bold tracking-widest ${activeTier === 'PAID' ? 'text-amber-400' : 'text-slate-400'}`}>DEDICATED_PAID</span>
              </button>
            </div>

            <div className="p-4 bg-cyan-500/5 border border-cyan-500/20 rounded-lg space-y-4">
              {activeTier === 'FREE' ? (
