import React from 'react';
import { JarvisStatus } from '../types';

interface HudCoreProps {
  status: JarvisStatus;
}

const HudCore: React.FC<HudCoreProps> = ({ status }) => {
  const getTheme = () => {
    switch (status) {
      case JarvisStatus.LISTENING: return { color: '#00f2ff', glow: 'rgba(0, 242, 255, 0.6)', speed: '8s' };
      case JarvisStatus.THINKING: return { color: '#7000ff', glow: 'rgba(112, 0, 255, 0.6)', speed: '3s' };
      case JarvisStatus.SPEAKING: return { color: '#0041ff', glow: 'rgba(0, 65, 255, 0.8)', speed: '6s' };
      case JarvisStatus.DIAGNOSTIC: return { color: '#ffaa00', glow: 'rgba(255, 170, 0, 0.6)', speed: '1.5s' };
      case JarvisStatus.EXECUTING: return { color: '#10b981', glow: 'rgba(16, 185, 129, 0.6)', speed: '4s' };
      default: return { color: '#00f2ff', glow: 'rgba(0, 242, 255, 0.2)', speed: '15s' };
    }
  };

  const { color, glow, speed } = getTheme();

  return (
    <div className="relative flex items-center justify-center w-[700px] h-[700px] perspective-[2000px]">
      <div className="absolute inset-0 flex items-center justify-center transform-gpu rotate-x-[25deg]">

        {/* Layer 1: Global Grid Mask */}
        <div className="absolute w-full h-full border border-cyan-500/5 rounded-full scale-125 opacity-20" />

        {/* Layer 2: Main Orbital Rings */}
        {[1, 2, 3].map((i) => (
          <svg key={i} className={`absolute w-[${90 - i * 10}%] h-[${90 - i * 10}%] opacity-30`} viewBox="0 0 100 100" 
               style={{ animation: `spin ${parseInt(speed) * (1 + i * 0.5)}s linear infinite ${i % 2 === 0 ? 'reverse' : ''}` }}>
            <circle cx="50" cy="50" r={48 - i * 4} fill="none" stroke={color} strokeWidth="0.15" strokeDasharray={`${10 + i * 5} ${5 + i * 2}`} />
          </svg>
        ))}

        {/* Layer 3: Tactical Data Segments */}
        <svg className="absolute w-[80%] h-[80%] opacity-40" viewBox="0 0 100 100" style={{ animation: `spin 12s linear infinite` }}>
          <defs>
            <linearGradient id="segmentGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor={color} stopOpacity="0" />
              <stop offset="50%" stopColor={color} stopOpacity="0.8" />
              <stop offset="100%" stopColor={color} stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d="M 50 2 A 48 48 0 0 1 98 50" fill="none" stroke="url(#segmentGrad)" strokeWidth="1" strokeLinecap="round" />
          <path d="M 50 98 A 48 48 0 0 1 2 50" fill="none" stroke="url(#segmentGrad)" strokeWidth="1" strokeLinecap="round" />
        </svg>

        {/* Layer 4: Central Neural Prism */}
        <div className="relative w-80 h-80 flex items-center justify-center">
          {/* Pulsing Aura */}
          <div className={`absolute inset-0 rounded-full transition-all duration-1000 ${status !== JarvisStatus.IDLE ? 'scale-110 opacity-40' : 'scale-100 opacity-10'}`}
               style={{ background: `radial-gradient(circle, ${glow} 0%, transparent 70%)` }} />

          {/* Core Geometry */}
          <div className="relative w-48 h-48">
             <svg className="absolute inset-0 w-full h-full animate-[spin_20s_linear_infinite]" viewBox="0 0 100 100">
               <polygon points="50,10 90,30 90,70 50,90 10,70 10,30" fill="none" stroke={color} strokeWidth="0.8" className="opacity-60" />
