  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="w-full max-w-lg glass border border-cyan-500/40 rounded-3xl shadow-[0_0_80px_rgba(0,242,255,0.15)] overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="flex items-center justify-between px-8 py-5 border-b border-cyan-500/20 bg-cyan-500/5">
          <div className="flex items-center gap-3">
            <Settings2 className="w-6 h-6 text-cyan-400" />
