          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/5 rounded-full transition-all text-slate-500 hover:text-cyan-400">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scroll">

          {/* Neural Engine Config */}
          <div className="space-y-6">
            <h3 className="text-[11px] font-orbitron text-cyan-500/80 uppercase tracking-[0.2em] flex items-center gap-2">
              <Layers className="w-3.5 h-3.5" /> Neural_Engine_Protocol
            </h3>

            <div className="grid grid-cols-3 gap-2">
              {(['Gemini', 'GPT', 'Local'] as AiModel[]).map((m) => (
                <button
                  key={m}
                  onClick={() => setSelectedModel(m)}
                  className={`py-2 px-1 rounded border text-[9px] font-orbitron transition-all ${
