                >
                  {m}
                </button>
              ))}
            </div>

            <div className="space-y-3 pt-2">
              <div className="flex items-center gap-2 text-[10px] font-orbitron text-slate-400 uppercase tracking-widest">
                <Volume2 className="w-3.5 h-3.5 text-cyan-400" /> Vocal_Sensing_ID
              </div>
              <select 
                value={selectedVoice}
                onChange={(e) => setSelectedVoice(e.target.value)}
                className="w-full bg-black/40 border border-white/10 text-[10px] font-orbitron text-cyan-400 px-4 py-2.5 rounded focus:outline-none focus:border-cyan-500/40 appearance-none cursor-pointer"
              >
                {voices.map(v => <option key={v} value={v}>{v.toUpperCase()}_PROTOCOL</option>)}
              </select>
            </div>
          </div>

          {/* Visual Interface Config */}
          <div className="pt-8 border-t border-white/5 space-y-6">
            <h3 className="text-[11px] font-orbitron text-cyan-500/80 uppercase tracking-[0.2em] flex items-center gap-2">
              <Palette className="w-3.5 h-3.5" /> HUD_Visual_Protocol
            </h3>

            <div className="flex items-center justify-between gap-4">
              <span className="text-[10px] font-orbitron text-slate-400 uppercase tracking-widest">Theme_Select</span>
              <div className="flex gap-3">
                {(['CYAN', 'RED', 'PURPLE', 'GREEN'] as JarvisTheme[]).map((t) => (
                  <button
                    key={t}
                    onClick={() => setTheme(t)}
                    className={`w-6 h-6 rounded-full border-2 transition-all ${
                      theme === t ? 'border-white scale-125' : 'border-transparent opacity-40 hover:opacity-100'
                    }`}
                    style={{ 
                      backgroundColor: t === 'CYAN' ? '#00f2ff' : t === 'RED' ? '#ff003c' : t === 'PURPLE' ? '#7000ff' : '#10b981' 
                    }}
                  />
                ))}
              </div>
            </div>
          </div>

          {/* Telemetry Usage */}
          <div className="pt-8 border-t border-white/5 space-y-6">
            <h3 className="text-[11px] font-orbitron text-cyan-500/80 uppercase tracking-[0.2em] flex items-center gap-2">
