            <span className="text-[10px] font-orbitron text-slate-300">STATUS: {status}</span>
          </div>
          <button onClick={stopLive} className="px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 font-bold hover:bg-red-600 hover:text-white transition-all"><Power className="w-3.5 h-3.5 inline mr-2" /> EMERGENCY</button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 pb-0 gap-6 relative">
        <ChatHistoryPanel isVisible={isHistoryVisible} activeSessionId={activeSessionId} onSelectSession={setActiveSessionId} onNewChat={stopLive} />
        {isMemoryVisible && <div className="w-96 h-full z-40"><MemoryPanel memories={memories} personality={personality} userIdentity={userIdentity} onAddMemory={(c, cat) => setMemories(p => [{ id: Math.random().toString(), content: c, category: cat, timestamp: Date.now() }, ...p])} onDeleteMemory={(id) => setMemories(p => p.filter(m => m.id !== id))} onUpdatePersonality={setPersonality} onUpdateIdentity={setUserIdentity} /></div>}
        <SystemMetrics />

        <div className="flex-1 flex flex-col gap-0 relative">
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40">
