import React from 'react';
import { JarvisStatus, JarvisTheme } from '../types';

interface HudCoreProps {
  status: JarvisStatus;
  theme: JarvisTheme;
}

const HudCore: React.FC<HudCoreProps> = ({ status, theme }) => {
  const getThemeData = () => {
    const baseColor = theme === 'RED' ? '#ff003c' : theme === 'PURPLE' ? '#7000ff' : theme === 'GREEN' ? '#10b981' : '#00f2ff';
    const baseGlow = theme === 'RED' ? 'rgba(255, 0, 60, 0.4)' : theme === 'PURPLE' ? 'rgba(112, 0, 255, 0.4)' : theme === 'GREEN' ? 'rgba(16, 185, 129, 0.4)' : 'rgba(0, 242, 255, 0.4)';

    switch (status) {
      case JarvisStatus.LISTENING: return { color: baseColor, glow: baseGlow, speed: '10s' };
      case JarvisStatus.THINKING: return { color: '#ffffff', glow: 'rgba(255, 255, 255, 0.6)', speed: '4s' };
      case JarvisStatus.SPEAKING: return { color: '#0041ff', glow: 'rgba(0, 65, 255, 0.8)', speed: '8s' };
      default: return { color: baseColor, glow: baseGlow, speed: '20s' };
    }
  };

  const { color, glow, speed } = getThemeData();

  return (
    <div className="relative flex items-center justify-center w-[600px] h-[600px] perspective-[1500px]">
      <div className="absolute inset-0 flex items-center justify-center transform-gpu rotate-x-[15deg]">
        <svg className="absolute w-[90%] h-[90%] opacity-10" viewBox="0 0 100 100" style={{ animation: `spin ${speed} linear infinite` }}>
          <circle cx="50" cy="50" r="48" fill="none" stroke={color} strokeWidth="0.2" strokeDasharray="1 3" />
        </svg>
        <svg className="absolute w-[75%] h-[75%] opacity-20" viewBox="0 0 100 100" style={{ animation: `spin 15s linear infinite reverse` }}>
          <circle cx="50" cy="50" r="45" fill="none" stroke={color} strokeWidth="1" strokeDasharray="0.5 15" />
        </svg>
        <div className="relative w-96 h-96 flex items-center justify-center">
          <svg className="absolute w-full h-full inset-0 z-0" viewBox="0 0 100 100">
            <circle cx="50" cy="50" r="30" fill="none" stroke={color} strokeWidth="0.8" className={status !== JarvisStatus.IDLE ? 'animate-pulse' : ''} style={{ filter: `drop-shadow(0 0 15px ${glow})` }} />
          </svg>
          <div className="relative w-64 h-64 rounded-full overflow-hidden flex items-center justify-center z-10">
            <img src="https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ3Z1OHB1Z3p6ZWlyYmx4ZWp6Z3Z1OHB1Z3p6ZWlyYmx4ZWp6Z3Z1JnB0X3JlZGlyZWN0PTEmZXA9djFfaW50ZXJuYWxfZ2lmX2J5X2lkJmN0PWc/3o7TKMGpxV9YvJ6h6o/giphy.gif" alt="JARVIS CORE" className={`w-full h-full object-cover mix-blend-screen transition-all duration-1000 ${status !== JarvisStatus.IDLE ? 'scale-110' : 'scale-90 opacity-40'}`} style={{ filter: `drop-shadow(0 0 20px ${color})` }} />
          </div>
        </div>
      </div>
      <style>{` @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } } `}</style>
    </div>
  );
};

