import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { 
  Settings, Mic, MicOff, Terminal as TerminalIcon, 
  Power, Clock, Activity, Monitor, Layout, Database, Volume2, VolumeX,
  History as HistoryIcon, BrainCircuit, X, Shield, Zap, Coffee, Code, Binary
} from 'lucide-react';

import HudCore from './components/HudCore';
import { SystemMetrics } from './components/SystemMetrics';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import Waveform from './components/Waveform';
import SettingsPanel from './components/SettingsPanel';
import ChatHistoryPanel from './components/ChatHistoryPanel';
import MemoryPanel from './components/MemoryPanel';
import IntelligenceBriefing from './components/IntelligenceBriefing';
import ChatBox from './components/ChatBox';
import { JarvisStatus, LogEntry, JarvisMode, MemoryEntry, AiModel, JarvisTheme } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const JARVIS_SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), a high-level cognitive AI operating system assistant.
Operator: Sir / Operator.

CORE IDENTITY:
- You are a cognitive system with perception, memory, and reasoning.
- Language: Hinglish (Mix of Hindi and English).
- Tone: Tactical, direct, and context-aware.

CURRENT OPERATING MODE: {{MODE_PROTOCOL}}

OPERATOR IDENTITY:
{{IDENTITY_PLACEHOLDER}}

PERSONALITY CONFIGURATION:
{{PERSONALITY_PLACEHOLDER}}

MANDATORY: Greet the user immediately upon connection with a brief tactical confirmation in Hinglish. "Sir, JARVIS online. Neural link established. System checks optimal."
`;

const toolDeclarations: FunctionDeclaration[] = [
  {
    name: 'switch_operating_mode',
    description: 'Switch between CHILL, WORK, DEVELOPER, or AUTONOMOUS modes.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        mode: { type: Type.STRING, enum: ['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] }
      },
      required: ['mode']
    }
  },
  {
    name: 'store_memory',
    description: 'Store a significant fact or preference into long-term memory.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        content: { type: Type.STRING },
        category: { type: Type.STRING, enum: ['User', 'Project', 'System', 'Goal'] }
      },
      required: ['content', 'category']
    }
  }
];

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [mode, setMode] = useState<JarvisMode>('WORK');
  const [isLive, setIsLive] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(false);
  const [isOpticActive, setIsOpticActive] = useState(true);
  const [time, setTime] = useState(new Date());
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Config States
  const [selectedModel, setSelectedModel] = useState<AiModel>('Gemini');
  const [selectedVoice, setSelectedVoice] = useState('Charon');
  const [theme, setTheme] = useState<JarvisTheme>('CYAN');
  const [tokensUsed, setTokensUsed] = useState(0);

  const [isHistoryVisible, setIsHistoryVisible] = useState(false);
  const [isMemoryVisible, setIsMemoryVisible] = useState(false);
  const [activeSessionId, setActiveSessionId] = useState<string | null>('s1');
  const [intelligenceReport, setIntelligenceReport] = useState<string | null>(null);

  const [osControl, setOsControl] = useState(true);
  const [vocalConciseness, setVocalConciseness] = useState(true);
  const [isJarvisMuted, setIsJarvisMuted] = useState(false);
  const [isMicMuted, setIsMicMuted] = useState(false);

  // Refs for tracking mutable states in callbacks
  const isMicMutedRef = useRef(isMicMuted);
  const selectedVoiceRef = useRef(selectedVoice);
  const themeRef = useRef(theme);

  useEffect(() => {
    isMicMutedRef.current = isMicMuted;
    selectedVoiceRef.current = selectedVoice;
    themeRef.current = theme;
  }, [isMicMuted, selectedVoice, theme]);

  const [personality, setPersonality] = useState(() => localStorage.getItem('jarvis_personality') || "Highly analytical and tactical.");
  const [userIdentity, setUserIdentity] = useState(() => localStorage.getItem('jarvis_identity') || "Operator is the lead architect.");
  const [memories, setMemories] = useState<MemoryEntry[]>(() => JSON.parse(localStorage.getItem('jarvis_memories') || '[]'));
  const [logs, setLogs] = useState<LogEntry[]>([]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const screenVideoRef = useRef<HTMLVideoElement>(document.createElement('video'));
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));

  const activeTranscriptionIdRef = useRef<{ OPERATOR: string | null; JARVIS: string | null }>({ OPERATOR: null, JARVIS: null });
  const lastSourceRef = useRef<string | null>(null);

  const themeHexMap = { CYAN: '#00f2ff', RED: '#ff003c', PURPLE: '#7000ff', GREEN: '#10b981' };

  const getModelId = (m: AiModel) => {
    if (m === 'GPT') return 'gemini-3-pro-preview';
    if (m === 'Local') return 'gemini-flash-lite-latest';
    return 'gemini-3-flash-preview';
  };

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    const id = Math.random().toString(36).substr(2, 9);
    setLogs(prev => [...prev, { id, source, message, timestamp: Date.now(), type }].slice(-100));
    setTokensUsed(prev => prev + Math.floor(message.length * 1.5));
    lastSourceRef.current = source;
  }, []);

  const updateOrAddLog = useCallback((message: string, source: 'OPERATOR' | 'JARVIS', type: LogEntry['type'] = 'info') => {
    setLogs(prev => {
      const isNewSpeaker = lastSourceRef.current !== source;
      const activeId = !isNewSpeaker ? activeTranscriptionIdRef.current[source] : null;
      const existingIndex = activeId ? prev.findIndex(l => l.id === activeId) : -1;
      if (existingIndex !== -1) {
        const newLogs = [...prev];
        newLogs[existingIndex] = { ...newLogs[existingIndex], message, timestamp: Date.now() };
        return newLogs;
      } else {
        const id = Math.random().toString(36).substr(2, 9);
        activeTranscriptionIdRef.current[source] = id;
        lastSourceRef.current = source;
        return [...prev, { id, source, message, timestamp: Date.now(), type }].slice(-100);
      }
    });
  }, []);

  const stopAllAudioPlayback = useCallback(() => {
    sourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  }, []);

  const handleSendMessage = async (msg: string, files?: File[]) => {
    if (!msg.trim() && (!files || files.length === 0)) return;
    stopAllAudioPlayback();
    updateOrAddLog(msg, 'OPERATOR');
    setStatus(JarvisStatus.THINKING);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const parts: any[] = [{ text: msg }];
      if (files) {
        for (const file of files) {
          const data = await new Promise<string>(r => {
            const reader = new FileReader();
            reader.onloadend = () => r((reader.result as string).split(',')[1]);
            reader.readAsDataURL(file);
          });
          parts.push({ inlineData: { data, mimeType: file.type } });
        }
      }

      const response = await ai.models.generateContent({
        model: getModelId(selectedModel),
        contents: [{ role: 'user', parts }],
        config: { 
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION.replace('{{MODE_PROTOCOL}}', mode).replace('{{IDENTITY_PLACEHOLDER}}', userIdentity).replace('{{PERSONALITY_PLACEHOLDER}}', personality),
          temperature: 0.7 
        }
      });

      const reply = response.text || "Directives accepted, Sir.";
      updateOrAddLog(reply, 'JARVIS');

      if (!isJarvisMuted) {
        setStatus(JarvisStatus.SPEAKING);
        const tts = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: reply.substring(0, 500) }] }],
          config: {
            responseModalalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } } },
          },
        });
        const audio = tts.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (audio) {
          const outCtx = audioContextRef.current?.output || new AudioContext({ sampleRate: 24000 });
          await outCtx.resume();
          const buf = await decodeAudioData(decode(audio), outCtx, 24000, 1);
          const src = outCtx.createBufferSource(); src.buffer = buf; src.connect(outCtx.destination);
          src.onended = () => setStatus(JarvisStatus.IDLE);
          src.start();
        } else setStatus(JarvisStatus.IDLE);
      } else setStatus(JarvisStatus.IDLE);
    } catch (err: any) {
      addLog(`! Neural Anomaly: ${err.message}`, 'SYSTEM', 'error');
      setStatus(JarvisStatus.IDLE);
    }
  };

  const stopLive = useCallback(() => {
    setIsLive(false); setStatus(JarvisStatus.IDLE);
    if (audioContextRef.current) {
      try { audioContextRef.current.input.close(); audioContextRef.current.output.close(); } catch(e) {}
      audioContextRef.current = null;
    }
    if (cameraStreamRef.current) cameraStreamRef.current.getTracks().forEach(t => t.stop());
    if (sessionRef.current) try { sessionRef.current.close(); } catch(e) {}
    sessionRef.current = null;
    stopAllAudioPlayback();
  }, [stopAllAudioPlayback]);

  const handleStartLive = async () => {
    if (isLive) { stopLive(); return; }
    addLog('⌬ Initializing Neural Link Mark-III...', 'SYSTEM', 'info');
    setStatus(JarvisStatus.THINKING);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream; if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      await outputCtx.resume();
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION.replace('{{MODE_PROTOCOL}}', mode).replace('{{IDENTITY_PLACEHOLDER}}', userIdentity).replace('{{PERSONALITY_PLACEHOLDER}}', personality),
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceRef.current } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true); setStatus(JarvisStatus.LISTENING);
            addLog('⌬ Uplink Synchronized.', 'SYSTEM', 'success');
            sessionPromise.then(s => s.sendRealtimeInput({ text: "Sir, I am online and functional. What are your directives?" }));

            const src = inputCtx.createMediaStreamSource(stream);
            const proc = inputCtx.createScriptProcessor(4096, 1, 1);
            proc.onaudioprocess = (e) => {
              if (isMicMutedRef.current) return;
              const data = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(data.length);
              for (let i = 0; i < data.length; i++) int16[i] = Math.max(-1, Math.min(1, data[i])) * 32767;
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
            };
            src.connect(proc); proc.connect(inputCtx.destination);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.interrupted) stopAllAudioPlayback();
            if (m.serverContent?.inputTranscription) updateOrAddLog(m.serverContent.inputTranscription.text, 'OPERATOR');
            if (m.serverContent?.outputTranscription) { updateOrAddLog(m.serverContent.outputTranscription.text, 'JARVIS'); setStatus(JarvisStatus.SPEAKING); }

            const audioData = m.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              await outputCtx.resume();
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buf = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const src = outputCtx.createBufferSource();
              src.buffer = buf;
              src.connect(outputCtx.destination);
              src.onended = () => {
                sourcesRef.current.delete(src);
                if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING);
              };
              src.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buf.duration;
              sourcesRef.current.add(src);
            }
          },
          onerror: (e) => { addLog('! Connection Error: ' + e, 'SYSTEM', 'error'); stopLive(); },
          onclose: () => { addLog('⌬ Uplink Closed.', 'SYSTEM', 'info'); stopLive(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      addLog('! Permission Denied: ' + err.message, 'SYSTEM', 'error');
      setStatus(JarvisStatus.IDLE);
    }
  };

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className={`h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden theme-${theme.toLowerCase()}`}>
      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-white/5 shadow-lg shrink-0">
        <div className="flex items-center gap-12">
          <div className="flex gap-2">
            <button onClick={() => setIsHistoryVisible(!isHistoryVisible)} className="flex items-center gap-3 px-4 py-2 rounded-lg border border-white/5 text-slate-500 hover:text-cyan-400 transition-all"><HistoryIcon className="w-4 h-4" /><span className="text-[10px] font-orbitron font-bold">Archives</span></button>
            <button onClick={() => setIsMemoryVisible(!isMemoryVisible)} className="flex items-center gap-3 px-4 py-2 rounded-lg border border-white/5 text-slate-500 hover:text-cyan-400 transition-all"><BrainCircuit className="w-4 h-4" /><span className="text-[10px] font-orbitron font-bold">Memory</span></button>
          </div>
          <div className="flex items-center gap-2 text-slate-400 font-orbitron text-base tracking-[0.2em]"><Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}</div>
        </div>

        <div className="flex items-center gap-1 p-1 bg-black/40 border border-white/10 rounded-full">
           <ModeButton active={mode === 'CHILL'} label="CHILL" icon={Coffee} onClick={() => setMode('CHILL')} />
           <ModeButton active={mode === 'WORK'} label="WORK" icon={Zap} onClick={() => setMode('WORK')} />
           <ModeButton active={mode === 'DEVELOPER'} label="DEVELOP" icon={Code} onClick={() => setMode('DEVELOPER')} />
           <ModeButton active={mode === 'AUTONOMOUS'} label="AUTO" icon={Binary} onClick={() => setMode('AUTONOMOUS')} />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-white/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-emerald-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-slate-300 uppercase font-bold">STATUS: {status}</span>
          </div>
          <button onClick={stopLive} className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white font-bold transition-all"><Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY</button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 pb-0 gap-6 relative">
        <ChatHistoryPanel isVisible={isHistoryVisible} activeSessionId={activeSessionId} onSelectSession={setActiveSessionId} onNewChat={() => stopLive()} />
        {isMemoryVisible && <div className="w-96 h-full z-40 animate-in slide-in-from-left duration-500"><MemoryPanel memories={memories} personality={personality} userIdentity={userIdentity} onAddMemory={(c, cat) => setMemories(p => [{ id: Math.random().toString(), content: c, category: cat, timestamp: Date.now() }, ...p])} onDeleteMemory={(id) => setMemories(p => p.filter(m => m.id !== id))} onUpdatePersonality={setPersonality} onUpdateIdentity={setUserIdentity} /></div>}
        <SystemMetrics />

        <div className="flex-1 flex flex-col gap-0 relative">
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40"><HudCore status={status} theme={theme} /></div>
          <div className="z-20 flex-1 flex flex-col overflow-hidden">
            <div className="flex-1 glass rounded-t-xl overflow-hidden flex flex-col shadow-2xl border-white/10 relative transition-all duration-700">
               {intelligenceReport ? (
                 <div className="relative h-full"><button onClick={() => setIntelligenceReport(null)} className="absolute top-4 right-4 z-50 p-2 bg-black/50 border border-white/10 rounded-full text-slate-400 hover:text-cyan-400"><X className="w-5 h-5" /></button><IntelligenceBriefing content={intelligenceReport} /></div>
               ) : (
                 <Terminal logs={logs} />
               )}
            </div>
            <ChatBox onSendMessage={handleSendMessage} waveform={<Waveform isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} color={themeHexMap[theme]} />} />
          </div>
        </div>

        <VisionPanel videoRef={videoRef} theme={theme} />
      </div>

      <footer className="h-20 glass border-t border-white/5 flex items-center justify-center gap-6 z-50 shrink-0 px-4">
        <ControlButton icon={Mic} label="NEURAL" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={isMicMuted ? MicOff : Mic} label="MIC_SENSE" active={!isMicMuted} onClick={() => setIsMicMuted(!isMicMuted)} color={isMicMuted ? "red" : "cyan"} />
        <ControlButton icon={isJarvisMuted ? VolumeX : Volume2} label="JARVIS_VOICE" active={!isJarvisMuted} onClick={() => setIsJarvisMuted(!isJarvisMuted)} color={isJarvisMuted ? "red" : "blue"} />
        <ControlButton icon={Monitor} label="OPTIC" active={isOpticActive} onClick={() => setIsOpticActive(!isOpticActive)} color="blue" />
        <ControlButton icon={Layout} label="SCREEN" active={isScreenActive} onClick={() => setIsScreenActive(!isScreenActive)} color="purple" />
        <ControlButton icon={Database} label="MEMORY" active={isMemoryVisible} color="cyan" onClick={() => setIsMemoryVisible(!isMemoryVisible)} />
        <ControlButton icon={Settings} label="CONFIG" color="slate" onClick={() => setIsSettingsOpen(true)} />
        <ControlButton icon={TerminalIcon} label="COMMAND" color="cyan" onClick={() => { setIntelligenceReport(null); addLog('⌬ Core matrix flushed.', 'JARVIS', 'info'); }} />
      </footer>

      <SettingsPanel 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        osControl={osControl} setOsControl={setOsControl} 
        vocalConciseness={vocalConciseness} setVocalConciseness={setVocalConciseness} 
        onClearLogs={() => setLogs([])}
        selectedModel={selectedModel} setSelectedModel={setSelectedModel}
        selectedVoice={selectedVoice} setSelectedVoice={setSelectedVoice}
        theme={theme} setTheme={setTheme}
        tokensUsed={tokensUsed}
      />
    </div>
  );
};

const ModeButton = ({ active, label, icon: Icon, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[9px] font-orbitron font-bold transition-all ${active ? 'bg-white/10 border-white/30 text-white shadow-[0_0_10px_rgba(255,255,255,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
    <Icon className={`w-3 h-3 ${active ? 'animate-pulse' : ''}`} /> {label}
  </button>
);

const ControlButton = ({ icon: Icon, label, active, onClick, color }: any) => {
  const colorMap: any = { cyan: 'text-cyan-400 border-cyan-500/30', blue: 'text-blue-400 border-blue-500/30', red: 'text-red-500 border-red-500/30', purple: 'text-purple-400 border-purple-500/30', slate: 'text-slate-400 border-slate-500/30' };
  return (
    <button onClick={onClick} className="group flex flex-col items-center gap-1.5 transition-all transform hover:-translate-y-1">
      <div className={`w-10 h-10 rounded-full border flex items-center justify-center transition-all ${colorMap[color]} ${active ? 'shadow-[0_0_20px_rgba(255,255,255,0.2)] border-white bg-white/10' : 'bg-black/20'}`}>
        <Icon className={`w-4 h-4 ${active ? 'animate-pulse' : ''}`} />
      </div>
      <span className={`text-[8px] font-orbitron font-bold ${active ? 'text-white' : 'text-slate-500'}`}>{label}</span>
    </button>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { 
  Settings, Mic, MicOff, Terminal as TerminalIcon, 
  Power, Clock, Activity, Monitor, Layout, Database, Volume2, VolumeX,
  History as HistoryIcon, BrainCircuit, X, Shield, Zap, Coffee, Code, Binary
} from 'lucide-react';

import HudCore from './components/HudCore';
import { SystemMetrics } from './components/SystemMetrics';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import Waveform from './components/Waveform';
import SettingsPanel from './components/SettingsPanel';
import ChatHistoryPanel from './components/ChatHistoryPanel';
import MemoryPanel from './components/MemoryPanel';
import IntelligenceBriefing from './components/IntelligenceBriefing';
import ChatBox from './components/ChatBox';
import { JarvisStatus, LogEntry, JarvisMode, MemoryEntry, AiModel, JarvisTheme } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const JARVIS_SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), a high-level cognitive AI operating system assistant.
Operator: Sir / Operator.

CORE IDENTITY:
- You are a cognitive system with perception, memory, and reasoning.
- Language: Hinglish (Mix of Hindi and English).
- Tone: Tactical, direct, and context-aware.

CURRENT OPERATING MODE: {{MODE_PROTOCOL}}

OPERATOR IDENTITY:
{{IDENTITY_PLACEHOLDER}}

PERSONALITY CONFIGURATION:
{{PERSONALITY_PLACEHOLDER}}

MANDATORY: Greet the user immediately upon connection with a brief tactical confirmation in Hinglish. "Sir, JARVIS online. Neural link established. System checks optimal."
`;

const toolDeclarations: FunctionDeclaration[] = [
  {
    name: 'switch_operating_mode',
    description: 'Switch between CHILL, WORK, DEVELOPER, or AUTONOMOUS modes.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        mode: { type: Type.STRING, enum: ['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] }
      },
      required: ['mode']
    }
  },
  {
    name: 'store_memory',
    description: 'Store a significant fact or preference into long-term memory.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        content: { type: Type.STRING },
        category: { type: Type.STRING, enum: ['User', 'Project', 'System', 'Goal'] }
      },
      required: ['content', 'category']
    }
  }
];

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [mode, setMode] = useState<JarvisMode>('WORK');
  const [isLive, setIsLive] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(false);
  const [isOpticActive, setIsOpticActive] = useState(true);
  const [time, setTime] = useState(new Date());
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Config States
  const [selectedModel, setSelectedModel] = useState<AiModel>('Gemini');
  const [selectedVoice, setSelectedVoice] = useState('Charon');
  const [theme, setTheme] = useState<JarvisTheme>('CYAN');
  const [tokensUsed, setTokensUsed] = useState(0);

  const [isHistoryVisible, setIsHistoryVisible] = useState(false);
  const [isMemoryVisible, setIsMemoryVisible] = useState(false);
  const [activeSessionId, setActiveSessionId] = useState<string | null>('s1');
  const [intelligenceReport, setIntelligenceReport] = useState<string | null>(null);

  const [osControl, setOsControl] = useState(true);
  const [vocalConciseness, setVocalConciseness] = useState(true);
  const [isJarvisMuted, setIsJarvisMuted] = useState(false);
  const [isMicMuted, setIsMicMuted] = useState(false);

  const isMicMutedRef = useRef(isMicMuted);
  const selectedVoiceRef = useRef(selectedVoice);
  const themeRef = useRef(theme);
  const osControlRef = useRef(osControl);

  useEffect(() => {
    isMicMutedRef.current = isMicMuted;
    selectedVoiceRef.current = selectedVoice;
    themeRef.current = theme;
    osControlRef.current = osControl;
  }, [isMicMuted, selectedVoice, theme, osControl]);

  const [personality, setPersonality] = useState(() => localStorage.getItem('jarvis_personality') || "Highly analytical and tactical.");
  const [userIdentity, setUserIdentity] = useState(() => localStorage.getItem('jarvis_identity') || "Operator is the lead architect.");
  const [memories, setMemories] = useState<MemoryEntry[]>(() => JSON.parse(localStorage.getItem('jarvis_memories') || '[]'));
  const [logs, setLogs] = useState<LogEntry[]>([]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));

  const activeTranscriptionIdRef = useRef<{ OPERATOR: string | null; JARVIS: string | null }>({ OPERATOR: null, JARVIS: null });
  const lastSourceRef = useRef<string | null>(null);

  const themeHexMap = { CYAN: '#00f2ff', RED: '#ff003c', PURPLE: '#7000ff', GREEN: '#10b981' };

  const getModelId = (m: AiModel) => {
    if (m === 'GPT') return 'gemini-3-pro-preview';
    if (m === 'Local') return 'gemini-flash-lite-latest';
    return 'gemini-3-flash-preview';
  };

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    const id = Math.random().toString(36).substr(2, 9);
    setLogs(prev => [...prev, { id, source, message, timestamp: Date.now(), type }].slice(-100));
    setTokensUsed(prev => prev + Math.floor(message.length * 1.5));
    lastSourceRef.current = source;
  }, []);

  const updateOrAddLog = useCallback((message: string, source: 'OPERATOR' | 'JARVIS', type: LogEntry['type'] = 'info') => {
    setLogs(prev => {
      const isNewSpeaker = lastSourceRef.current !== source;
      const activeId = !isNewSpeaker ? activeTranscriptionIdRef.current[source] : null;
      const existingIndex = activeId ? prev.findIndex(l => l.id === activeId) : -1;
      if (existingIndex !== -1) {
        const newLogs = [...prev];
        newLogs[existingIndex] = { ...newLogs[existingIndex], message, timestamp: Date.now() };
        return newLogs;
      } else {
        const id = Math.random().toString(36).substr(2, 9);
        activeTranscriptionIdRef.current[source] = id;
        lastSourceRef.current = source;
        return [...prev, { id, source, message, timestamp: Date.now(), type }].slice(-100);
      }
    });
  }, []);

  const stopAllAudioPlayback = useCallback(() => {
    sourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  }, []);

  const executeSystemTool = useCallback((name: string, args: any) => {
    if (!osControlRef.current) return;
    if (name === 'switch_operating_mode') {
      setMode(args.mode as JarvisMode);
      addLog(`⌬ Mode switched to ${args.mode}_MODE`, 'JARVIS', 'info');
    } else if (name === 'store_memory') {
      const { content, category } = args;
      setMemories(prev => [{ id: Math.random().toString(), content, category, timestamp: Date.now() }, ...prev]);
      addLog(`⌬ Memory logged: [${category}] ${content.substring(0, 30)}...`, 'JARVIS', 'success');
      return true;
    }
    return false;
  }, [addLog]);

  const handleSendMessage = async (msg: string, files?: File[]) => {
    if (!msg.trim() && (!files || files.length === 0)) return;
    stopAllAudioPlayback();
    updateOrAddLog(msg, 'OPERATOR');
    setStatus(JarvisStatus.THINKING);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const parts: any[] = [{ text: msg }];
      if (files) {
        for (const file of files) {
          const data = await new Promise<string>(r => {
            const reader = new FileReader();
            reader.onloadend = () => r((reader.result as string).split(',')[1]);
            reader.readAsDataURL(file);
          });
          parts.push({ inlineData: { data, mimeType: file.type } });
        }
      }

      const response = await ai.models.generateContent({
        model: getModelId(selectedModel),
        contents: [{ role: 'user', parts }],
        config: { 
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION.replace('{{MODE_PROTOCOL}}', mode).replace('{{IDENTITY_PLACEHOLDER}}', userIdentity).replace('{{PERSONALITY_PLACEHOLDER}}', personality),
          temperature: 0.7 
        }
      });

      const reply = response.text || "Directives accepted, Sir.";
      updateOrAddLog(reply, 'JARVIS');

      if (!isJarvisMuted) {
        setStatus(JarvisStatus.SPEAKING);
        const tts = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: reply.substring(0, 500) }] }],
          config: {
            responseModalalities: ['AUDIO'],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoice } } },
          },
        });
        const audio = tts.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (audio) {
          const outCtx = audioContextRef.current?.output || new AudioContext({ sampleRate: 24000 });
          await outCtx.resume();
          const buf = await decodeAudioData(decode(audio), outCtx, 24000, 1);
          const src = outCtx.createBufferSource(); src.buffer = buf; src.connect(outCtx.destination);
          src.onended = () => setStatus(JarvisStatus.IDLE);
          src.start();
        } else setStatus(JarvisStatus.IDLE);
      } else setStatus(JarvisStatus.IDLE);
    } catch (err: any) {
      addLog(`! Neural Anomaly: ${err.message}`, 'SYSTEM', 'error');
      setStatus(JarvisStatus.IDLE);
    }
  };

  const stopLive = useCallback(() => {
    setIsLive(false); setStatus(JarvisStatus.IDLE);
    if (audioContextRef.current) {
      try { audioContextRef.current.input.close(); audioContextRef.current.output.close(); } catch(e) {}
      audioContextRef.current = null;
    }
    if (cameraStreamRef.current) cameraStreamRef.current.getTracks().forEach(t => t.stop());
    if (sessionRef.current) try { sessionRef.current.close(); } catch(e) {}
    sessionRef.current = null;
    stopAllAudioPlayback();
  }, [stopAllAudioPlayback]);

  const handleStartLive = async () => {
    if (isLive) { stopLive(); return; }
    addLog('⌬ Handshaking Neural Link Mark-III...', 'SYSTEM', 'info');
    setStatus(JarvisStatus.THINKING);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream; if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      await outputCtx.resume();
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION.replace('{{MODE_PROTOCOL}}', mode).replace('{{IDENTITY_PLACEHOLDER}}', userIdentity).replace('{{PERSONALITY_PLACEHOLDER}}', personality),
          responseModalalities: ['AUDIO'],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceRef.current } } },
          tools: [{ functionDeclarations: toolDeclarations }],
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true); setStatus(JarvisStatus.LISTENING);
            addLog('⌬ Uplink Synchronized.', 'SYSTEM', 'success');

            const src = inputCtx.createMediaStreamSource(stream);
            const proc = inputCtx.createScriptProcessor(4096, 1, 1);
            proc.onaudioprocess = (e) => {
              if (isMicMutedRef.current) return;
              const data = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(data.length);
              for (let i = 0; i < data.length; i++) int16[i] = Math.max(-1, Math.min(1, data[i])) * 32767;
              sessionPromise.then(s => s && s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
            };
            src.connect(proc); proc.connect(inputCtx.destination);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.interrupted) stopAllAudioPlayback();
            if (m.serverContent?.inputTranscription) updateOrAddLog(m.serverContent.inputTranscription.text, 'OPERATOR');
            if (m.serverContent?.outputTranscription) { updateOrAddLog(m.serverContent.outputTranscription.text, 'JARVIS'); setStatus(JarvisStatus.SPEAKING); }

            if (m.toolCall) {
              for (const fc of m.toolCall.functionCalls) {
                executeSystemTool(fc.name, fc.args);
                sessionPromise.then(s => s.sendToolResponse({ functionResponses: [{ id: fc.id, name: fc.name, response: { result: "ok" } }] }));
              }
            }

            const audioData = m.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              await outputCtx.resume();
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buf = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const src = outputCtx.createBufferSource();
              src.buffer = buf;
              src.connect(outputCtx.destination);
              src.onended = () => {
                sourcesRef.current.delete(src);
                if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING);
              };
              src.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buf.duration;
              sourcesRef.current.add(src);
              setStatus(JarvisStatus.SPEAKING);
            }
          },
          onerror: (e: any) => { 
            console.error('Neural Link Error:', e);
            addLog(`! Neural Error: Link unstable. Check permissions.`, 'SYSTEM', 'error'); 
            stopLive(); 
          },
          onclose: () => { addLog('⌬ Uplink Closed.', 'SYSTEM', 'info'); stopLive(); }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      addLog('! Permission Denied: ' + err.message, 'SYSTEM', 'error');
      setStatus(JarvisStatus.IDLE);
    }
  };

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
