          </div>
          <div className="flex items-center gap-2 text-slate-400 font-orbitron text-base tracking-[0.2em]"><Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}</div>
        </div>

        <div className="flex items-center gap-1 p-1 bg-black/40 border border-white/10 rounded-full">
           <ModeButton active={mode === 'CHILL'} label="CHILL" icon={Coffee} onClick={() => setMode('CHILL')} />
           <ModeButton active={mode === 'WORK'} label="WORK" icon={Zap} onClick={() => setMode('WORK')} />
           <ModeButton active={mode === 'DEVELOPER'} label="DEVELOP" icon={Code} onClick={() => setMode('DEVELOPER')} />
           <ModeButton active={mode === 'AUTONOMOUS'} label="AUTO" icon={Binary} onClick={() => setMode('AUTONOMOUS')} />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-white/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-emerald-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-slate-300 uppercase font-bold">STATUS: {status}</span>
          </div>
          <button onClick={stopLive} className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white font-bold transition-all"><Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY</button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 pb-0 gap-6 relative">
        <ChatHistoryPanel isVisible={isHistoryVisible} activeSessionId={activeSessionId} onSelectSession={setActiveSessionId} onNewChat={() => stopLive()} />
        {isMemoryVisible && <div className="w-96 h-full z-40 animate-in slide-in-from-left duration-500"><MemoryPanel memories={memories} personality={personality} userIdentity={userIdentity} onAddMemory={(c, cat) => setMemories(p => [{ id: Math.random().toString(), content: c, category: cat, timestamp: Date.now() }, ...p])} onDeleteMemory={(id) => setMemories(p => p.filter(m => m.id !== id))} onUpdatePersonality={setPersonality} onUpdateIdentity={setUserIdentity} /></div>}
        <SystemMetrics />

        <div className="flex-1 flex flex-col gap-0 relative">
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40"><HudCore status={status} theme={theme} /></div>
          <div className="z-20 flex-1 flex flex-col overflow-hidden">
            <div className="flex-1 glass rounded-t-xl overflow-hidden flex flex-col shadow-2xl border-white/10 relative transition-all duration-700">
               {intelligenceReport ? (
                 <div className="relative h-full"><button onClick={() => setIntelligenceReport(null)} className="absolute top-4 right-4 z-50 p-2 bg-black/50 border border-white/10 rounded-full text-slate-400 hover:text-cyan-400"><X className="w-5 h-5" /></button><IntelligenceBriefing content={intelligenceReport} /></div>
               ) : (
                 <Terminal logs={logs} />
               )}
            </div>
            <ChatBox onSendMessage={handleSendMessage} waveform={<Waveform isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} color={themeHexMap[theme]} />} />
          </div>
        </div>

        <VisionPanel videoRef={videoRef} theme={theme} />
      </div>

      <footer className="h-20 glass border-t border-white/5 flex items-center justify-center gap-6 z-50 shrink-0 px-4">
        <ControlButton icon={Mic} label="NEURAL" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={isMicMuted ? MicOff : Mic} label="MIC_SENSE" active={!isMicMuted} onClick={() => setIsMicMuted(!isMicMuted)} color={isMicMuted ? "red" : "cyan"} />
        <ControlButton icon={isJarvisMuted ? VolumeX : Volume2} label="JARVIS_VOICE" active={!isJarvisMuted} onClick={() => setIsJarvisMuted(!isJarvisMuted)} color={isJarvisMuted ? "red" : "blue"} />
        <ControlButton icon={Monitor} label="OPTIC" active={isOpticActive} onClick={() => setIsOpticActive(!isOpticActive)} color="blue" />
        <ControlButton icon={Layout} label="SCREEN" active={isScreenActive} onClick={() => setIsScreenActive(!isScreenActive)} color="purple" />
        <ControlButton icon={Database} label="MEMORY" active={isMemoryVisible} color="cyan" onClick={() => setIsMemoryVisible(!isMemoryVisible)} />
        <ControlButton icon={Settings} label="CONFIG" color="slate" onClick={() => setIsSettingsOpen(true)} />
        <ControlButton icon={TerminalIcon} label="COMMAND" color="cyan" onClick={() => { setIntelligenceReport(null); addLog('⌬ Neural Matrix refreshed.', 'JARVIS', 'info'); }} />
      </footer>

      <SettingsPanel 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        osControl={osControl} setOsControl={setOsControl} 
        vocalConciseness={vocalConciseness} setVocalConciseness={setVocalConciseness} 
        onClearLogs={() => setLogs([])}
        selectedModel={selectedModel} setSelectedModel={setSelectedModel}
        selectedVoice={selectedVoice} setSelectedVoice={setSelectedVoice}
        theme={theme} setTheme={setTheme}
        tokensUsed={tokensUsed}
      />
    </div>
  );
};

